import raw from "@/data/disorders.json";
import type { DisorderData, Field, Row, RowRef, Section } from "./types";

/**
 * All study content. Generated by scripts/extract.py from the Google Doc.
 * Treat it as read-only and show it verbatim; never "fix" its wording.
 */
export const data = raw as DisorderData;

export const sections: Section[] = data.sections;

/** Sections that actually have rows (excludes empty headings like "Nerve Disorders"). */
export const quizzableSections: Section[] = sections.filter((s) => !s.empty && s.rows.length > 0);

export function getSection(id: string): Section | undefined {
  return sections.find((s) => s.id === id);
}

export function allRows(): RowRef[] {
  return quizzableSections.flatMap((section) => section.rows.map((row) => ({ section, row })));
}

export function rowsForSections(sectionIds: string[]): RowRef[] {
  const want = new Set(sectionIds);
  return allRows().filter((r) => want.has(r.section.id));
}

export function getRow(rowId: string): RowRef | undefined {
  return allRows().find((r) => r.row.id === rowId);
}

/** Header column whose text is the condition name. */
export function conditionColumn(section: Section): string {
  return section.columns[0];
}

/** First line of the condition cell; a short label for buttons and choices. */
export function conditionLabel(row: Row): string {
  return row.condition.split("\n")[0].trim();
}

/* ---------- Column → Field normalization ---------- */

const FIELD_RULES: [Field, RegExp][] = [
  // order matters: more specific first
  ["nonpharm", /non-?pharm/i],
  ["differentials", /differential/i],
  ["complications", /complication|referral/i],
  ["education", /education|prevention/i],
  ["pathophysiology", /pathophys/i],
  ["risk", /risk factor/i],
  ["etiology", /etiology|causes/i],
  ["diagnostics", /diagnos/i],
  ["presentation", /presentation|clinical features|key features/i],
  ["treatment", /treatment|management/i],
  ["definition", /definition|overview|what it is/i],
];

/** Map a column header to a canonical Field. Unrecognized headers (TSH, Notes, ...) → "other". */
export function fieldOf(column: string): Field {
  for (const [field, re] of FIELD_RULES) if (re.test(column)) return field;
  return "other";
}

export const FIELD_LABELS: Record<Field, string> = {
  definition: "Definition",
  etiology: "Etiology / Causes",
  risk: "Risk Factors",
  pathophysiology: "Pathophysiology",
  presentation: "Clinical Presentation",
  diagnostics: "Diagnostics",
  treatment: "Treatment / Management",
  nonpharm: "Non-Pharmacologic Management",
  education: "Patient Education",
  complications: "Complications / Referral",
  differentials: "Differentials",
  other: "Other",
};

/** The section's own column headers that map to `field` (usually 0 or 1). */
export function columnsForField(section: Section, field: Field): string[] {
  return section.columns.slice(1).filter((c) => fieldOf(c) === field);
}

/**
 * Verbatim text for a field in a row, or "" if the section has no such column or
 * the cell is empty. If a section has two columns for the same field, they are
 * joined with a blank line. Use `cellsForField` to keep them separate.
 */
export function cellValue(ref: RowRef, field: Field): string {
  return cellsForField(ref, field)
    .map((c) => c.text)
    .join("\n\n");
}

export function cellsForField(ref: RowRef, field: Field): { column: string; text: string }[] {
  return columnsForField(ref.section, field)
    .map((column) => ({ column, text: ref.row.cells[column] ?? "" }))
    .filter((c) => c.text.trim() !== "");
}

/** Non-empty cells of a row, excluding the condition column, in source order. */
export function filledCells(ref: RowRef): { column: string; field: Field; text: string }[] {
  return ref.section.columns
    .slice(1)
    .map((column) => ({ column, field: fieldOf(column), text: ref.row.cells[column] ?? "" }))
    .filter((c) => c.text.trim() !== "");
}

export function rowsWithImages(rows: RowRef[] = allRows()): RowRef[] {
  return rows.filter((r) => r.row.images.length > 0);
}
